<template>
  <section class="question-bank-page">
    <div class="page-header qb-header">
      <div><h2>題庫管理</h2><p class="page-desc">建立可重用題目，送主任審核後才可進入正式檢測。</p></div>
      <button class="primary" type="button" @click="showBankForm = !showBankForm">＋新增題庫</button>
    </div>

    <div v-if="showBankForm" class="card qb-form-card">
      <h3>新增題庫</h3>
      <div class="qb-form-grid"><label>題庫名稱<input v-model.trim="bankForm.name" maxlength="120" placeholder="例如：國一英文文法" /></label><label>說明<input v-model.trim="bankForm.description" maxlength="10000" placeholder="選填" /></label></div>
      <div class="qb-actions"><button class="ghost" @click="showBankForm = false">取消</button><button class="primary" :disabled="saving || !bankForm.name" @click="createBank">{{ saving ? '建立中…' : '建立題庫' }}</button></div>
    </div>

    <p v-if="error" class="qb-error" role="alert">{{ error }} <button class="ghost small" @click="loadBanks">重試</button></p>
    <div class="qb-layout">
      <aside class="card qb-banks"><div class="qb-card-title"><h3>我的題庫</h3><button class="ghost small" :disabled="loading" @click="loadBanks">重新整理</button></div><div v-if="loading" class="qb-empty">載入中…</div><div v-else-if="!banks.length" class="qb-empty">尚未建立題庫。</div><button v-for="bank in banks" :key="bank.id" type="button" :class="['qb-bank-row', { active: selectedBank?.id === bank.id }]" @click="selectBank(bank)"><strong>{{ bank.name }}</strong><span>{{ bank.items_count || 0 }} 題 · {{ bank.status === 'draft' ? '草稿' : bank.status }}</span></button></aside>

      <main v-if="selectedBank" class="card qb-content">
        <div class="qb-card-title"><div><h3>{{ selectedBank.name }}</h3><p class="muted">{{ selectedBank.description || '尚未填寫題庫說明' }}</p></div><label class="qb-filter">狀態<select v-model="filters.status" @change="loadItems"><option value="">全部</option><option value="draft">草稿</option><option value="pending_review">待審核</option><option value="approved">已核准</option><option value="retired">已退休</option></select></label></div>
        <div class="qb-toolbar"><label class="file-button">匯入 CSV<input type="file" accept=".csv,text/csv" @change="importCsv" /></label><span class="muted">必填欄位：question_type、prompt、knowledge_tag、difficulty</span></div>
        <div class="card qb-editor"><h4>{{ editing ? `建立第 ${editing.version_no + 1} 版` : '新增題目草稿' }}</h4><div class="qb-form-grid"><label>題型<select v-model="itemForm.question_type"><option value="single_choice">單選</option><option value="multiple_choice">複選</option><option value="true_false">是非</option><option value="fill_blank">填空</option><option value="short_answer">簡答</option></select></label><label>難度（1–5）<input v-model.number="itemForm.difficulty" type="number" min="1" max="5" /></label><label>知識標籤<input v-model.trim="itemForm.knowledge_tag" maxlength="120" placeholder="例如：英文／過去式" /></label><label>來源<select v-model="itemForm.source_type"><option value="internal">內部建立</option><option value="licensed">已授權素材</option><option value="ai_draft">AI 草稿</option><option value="other">其他</option></select></label></div><label>題目內容<textarea v-model.trim="itemForm.prompt" rows="3" maxlength="20000" placeholder="請輸入完整題目" /></label><div class="qb-form-grid"><label>選項（JSON 陣列，選填）<textarea v-model.trim="itemForm.choices" rows="2" placeholder='["A", "B"]' /></label><label>答案（JSON 陣列，選填）<textarea v-model.trim="itemForm.answer" rows="2" placeholder='["A"]' /></label></div><label>解析（選填）<textarea v-model.trim="itemForm.explanation" rows="2" maxlength="20000" /></label><div class="qb-actions"><button v-if="editing" class="ghost" @click="cancelEdit">取消改版</button><button class="primary" :disabled="saving || !itemForm.prompt || !itemForm.knowledge_tag" @click="saveItem">{{ saving ? '儲存中…' : editing ? '建立新版本' : '儲存草稿' }}</button></div></div>
        <div v-if="itemsLoading" class="qb-empty">題目載入中…</div><div v-else-if="!items.length" class="qb-empty">目前沒有符合條件的題目。</div><div v-else class="qb-table-wrap"><table class="qb-table"><thead><tr><th>題目</th><th>標籤</th><th>難度</th><th>版次</th><th>狀態</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.question_type }}</strong><small>{{ item.prompt }}</small></td><td>{{ item.knowledge_tag }}</td><td>{{ item.difficulty }}/5</td><td>v{{ item.version_no }}</td><td><span :class="['qb-status', `is-${item.status}`]">{{ statusLabel(item.status) }}</span></td><td class="qb-actions"><button v-if="item.status === 'draft'" class="ghost small" @click="submitReview(item)">送審</button><button v-if="item.status === 'pending_review' && isDirector" class="primary small" @click="approve(item)">核准</button><button v-if="['draft', 'pending_review', 'approved'].includes(item.status)" class="ghost small" @click="editItem(item)">建新版</button><button v-if="item.status !== 'retired' && isDirector" class="ghost small danger" @click="retire(item)">退休</button><button class="ghost small" @click="showVersions(item)">歷史</button></td></tr></tbody></table></div>
      </main>
      <main v-else class="card qb-empty qb-no-selection">請先從左側選擇題庫。</main>
    </div>
    <div v-if="versions.length" class="modal-overlay" @click.self="versions = []"><div class="modal qb-version-modal"><div class="qb-card-title"><h3>版本歷史</h3><button class="ghost" @click="versions = []">關閉</button></div><div v-for="version in versions" :key="version.id" class="qb-version-row"><div><strong>v{{ version.version_no }} · {{ statusLabel(version.status) }}</strong><small>{{ version.prompt }}</small></div><span>{{ version.reviewed_at ? '已審核' : '未審核' }}</span></div></div></div>
  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';

const props = defineProps({ branchId: [String, Number], userRole: String });
const base = `${import.meta.env.VITE_API_BASE || '/api'}/v1`;
const banks = ref([]); const selectedBank = ref(null); const items = ref([]); const versions = ref([]);
const loading = ref(false); const itemsLoading = ref(false); const saving = ref(false); const error = ref(''); const showBankForm = ref(false); const editing = ref(null);
const filters = reactive({ status: '' }); const bankForm = reactive({ name: '', description: '' });
const itemForm = reactive({ question_type: 'single_choice', prompt: '', choices: '', answer: '', explanation: '', knowledge_tag: '', difficulty: 3, source_type: 'internal' });
const isDirector = computed(() => ['director', 'super_admin'].includes(props.userRole));
function auth() { try { return JSON.parse(localStorage.getItem('alltrue_session') || '{}')?.access_token || ''; } catch { return ''; } }
async function api(path, options = {}) { const response = await fetch(`${base}${path}`, { ...options, headers: { Accept: 'application/json', Authorization: `Bearer ${auth()}`, ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body?.message || Object.values(body?.errors || {})?.flat?.()?.[0] || '操作失敗'); return body; }
function statusLabel(status) { return { draft: '草稿', pending_review: '待審核', approved: '已核准', retired: '已退休' }[status] || status; }
async function loadBanks() { if (!props.branchId) return; loading.value = true; error.value = ''; try { const result = await api(`/question-banks?campus_id=${encodeURIComponent(props.branchId)}`); banks.value = result.data || []; if (selectedBank.value) selectedBank.value = banks.value.find((bank) => bank.id === selectedBank.value.id) || null; if (!selectedBank.value && banks.value[0]) selectBank(banks.value[0]); } catch (e) { error.value = e.message; } finally { loading.value = false; } }
async function selectBank(bank) { selectedBank.value = bank; filters.status = ''; await loadItems(); }
async function loadItems() { if (!selectedBank.value) return; itemsLoading.value = true; try { const query = filters.status ? `?status=${encodeURIComponent(filters.status)}` : ''; items.value = (await api(`/question-banks/${selectedBank.value.id}/items${query}`)).data || []; } catch (e) { error.value = e.message; } finally { itemsLoading.value = false; } }
async function createBank() { saving.value = true; error.value = ''; try { const bank = (await api('/question-banks', { method: 'POST', body: JSON.stringify({ campus_id: Number(props.branchId), name: bankForm.name, description: bankForm.description || null }) })).data; showBankForm.value = false; Object.assign(bankForm, { name: '', description: '' }); await loadBanks(); selectBank(bank); } catch (e) { error.value = e.message; } finally { saving.value = false; } }
function parseJson(value) { if (!value.trim()) return null; const parsed = JSON.parse(value); if (!Array.isArray(parsed)) throw new Error('選項與答案必須是 JSON 陣列'); return parsed; }
async function saveItem() { saving.value = true; error.value = ''; try { const body = { ...itemForm, choices: parseJson(itemForm.choices), answer: parseJson(itemForm.answer), difficulty: Number(itemForm.difficulty) }; const path = editing.value ? `/question-bank-items/${editing.value.id}` : `/question-banks/${selectedBank.value.id}/items`; await api(path, { method: editing.value ? 'PATCH' : 'POST', body: JSON.stringify(body) }); cancelEdit(); await loadItems(); await loadBanks(); } catch (e) { error.value = e.message; } finally { saving.value = false; } }
function editItem(item) { editing.value = item; Object.assign(itemForm, { question_type: item.question_type, prompt: item.prompt, choices: item.choices ? JSON.stringify(item.choices) : '', answer: item.answer ? JSON.stringify(item.answer) : '', explanation: item.explanation || '', knowledge_tag: item.knowledge_tag, difficulty: item.difficulty, source_type: item.source_type || 'internal' }); }
function cancelEdit() { editing.value = null; Object.assign(itemForm, { question_type: 'single_choice', prompt: '', choices: '', answer: '', explanation: '', knowledge_tag: '', difficulty: 3, source_type: 'internal' }); }
async function changeItem(item, action) { try { await api(`/question-bank-items/${item.id}/${action}`, { method: 'POST' }); await loadItems(); await loadBanks(); } catch (e) { error.value = e.message; } }
function submitReview(item) { return changeItem(item, 'submit-review'); } function approve(item) { return changeItem(item, 'approve'); }
async function retire(item) { if (window.confirm('退休後保留歷史，但不再列為可用題目。確定嗎？')) await changeItem(item, 'retire'); }
async function showVersions(item) { try { versions.value = (await api(`/question-bank-items/${item.id}/versions`)).data || []; } catch (e) { error.value = e.message; } }
async function importCsv(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file || !selectedBank.value) return; saving.value = true; error.value = ''; try { const form = new FormData(); form.append('file', file); const result = await api(`/question-banks/${selectedBank.value.id}/items/import`, { method: 'POST', body: form }); error.value = `已匯入 ${result.count || 0} 題，全部進入待審核。`; await loadItems(); await loadBanks(); } catch (e) { error.value = e.message; } finally { saving.value = false; } }
watch(() => props.branchId, loadBanks); onMounted(loadBanks);
</script>

<style scoped>
.question-bank-page { max-width: 1480px; margin: 0 auto; } .qb-header, .qb-card-title, .qb-toolbar, .qb-actions { display: flex; align-items: center; justify-content: space-between; gap: 12px; } .qb-layout { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: 16px; margin-top: 16px; } .qb-banks, .qb-content { padding: 18px; min-width: 0; } .qb-bank-row { width: 100%; display: flex; flex-direction: column; align-items: flex-start; gap: 5px; border: 0; border-bottom: 1px solid var(--ds-border); background: transparent; padding: 13px 8px; text-align: left; cursor: pointer; color: var(--ds-text-primary); } .qb-bank-row.active { background: var(--ds-surface-subtle); border-left: 3px solid var(--ds-primary); } .qb-bank-row span, .qb-version-row small, .qb-table small { color: var(--ds-text-tertiary); font-size: 12px; display: block; margin-top: 4px; } .qb-form-card, .qb-editor { padding: 18px; margin-top: 16px; } .qb-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin: 12px 0; } label { display: flex; flex-direction: column; gap: 5px; color: var(--ds-text-secondary); font-size: 13px; } input, textarea, select { border: 1px solid var(--ds-border); border-radius: 8px; padding: 9px 10px; background: var(--ds-surface); color: var(--ds-text-primary); font: inherit; } .qb-toolbar { border-bottom: 1px solid var(--ds-border); padding: 14px 0; margin-bottom: 2px; } .file-button { display: inline-flex; flex-direction: row; align-items: center; background: var(--ds-primary); color: var(--ds-on-primary); border-radius: 8px; padding: 8px 12px; cursor: pointer; } .file-button input { display: none; } .qb-table-wrap { overflow-x: auto; } .qb-table { width: 100%; border-collapse: collapse; } .qb-table th, .qb-table td { padding: 11px 8px; border-bottom: 1px solid var(--ds-border); text-align: left; vertical-align: top; } .qb-table td.qb-actions { white-space: nowrap; justify-content: flex-start; flex-wrap: wrap; } .qb-status { border-radius: 999px; padding: 3px 8px; font-size: 12px; background: var(--ds-surface-subtle); } .is-approved { color: var(--ds-success); background: var(--ds-success-wash); } .is-pending_review { color: var(--ds-warning); background: var(--ds-warning-wash); } .is-retired { color: var(--ds-text-tertiary); } .qb-empty { color: var(--ds-text-tertiary); padding: 28px 10px; text-align: center; } .qb-no-selection { min-height: 260px; display: grid; place-items: center; } .qb-error { color: var(--ds-danger); margin: 12px 0; } .danger { color: var(--ds-danger); } .qb-version-modal { max-width: 720px; } .qb-version-row { display: flex; justify-content: space-between; gap: 16px; padding: 13px 0; border-bottom: 1px solid var(--ds-border); } .muted { color: var(--ds-text-tertiary); font-size: 13px; } @media (max-width: 860px) { .qb-layout { grid-template-columns: 1fr; } .qb-form-grid { grid-template-columns: 1fr; } .qb-table th:nth-child(2), .qb-table td:nth-child(2), .qb-table th:nth-child(3), .qb-table td:nth-child(3) { display: none; } }
</style>
